import random, math

def p_success(k, alpha, q):
    """Probabilità che su k campioni (con reinserimento) almeno alpha preferiscano il valore,
    se una frazione q della rete lo preferisce."""
    return sum(math.comb(k, i) * q**i * (1 - q)**(k - i) for i in range(alpha, k + 1))

def snowball(n=200, init_red=0.55, k=20, alpha=15, beta=20, seed=1, max_rounds=10_000):
    rng = random.Random(seed)
    pref = ["R" if i < int(n * init_red) else "B" for i in range(n)]
    rng.shuffle(pref)
    conf = [{"R": 0, "B": 0} for _ in range(n)]
    last = [None] * n
    streak = [0] * n
    decided = [None] * n
    rounds = 0
    while None in decided and rounds < max_rounds:
        rounds += 1
        for v in range(n):
            if decided[v] is not None:
                continue
            sample = [pref[rng.randrange(n)] for _ in range(k)]
            for col in ("R", "B"):
                if sample.count(col) >= alpha:
                    conf[v][col] += 1
                    if conf[v][col] > conf[v][pref[v]]:
                        pref[v] = col
                    streak[v] = streak[v] + 1 if last[v] == col else 1
                    last[v] = col
                    if streak[v] >= beta:
                        decided[v] = col
                    break
            else:
                streak[v] = 0      # nessuna maggioranza alpha: si azzera la striscia
    return rounds, decided

for q in (0.5, 0.6, 0.7, 0.8):
    print(f"q={q}: P[round riuscito] = {p_success(20, 15, q):.4f}")

for init in (0.55, 0.51):
    rounds, dec = snowball(init_red=init)
    print(f"iniziale rossi={init}: round={rounds}, decisi R={dec.count('R')}, B={dec.count('B')}")

