import hashlib, hmac

H = lambda b: hashlib.sha256(b).digest()

def merkle_root_and_proof(leaves, idx):
    """Radice Merkle e proof (lista di (fratello, fratello_a_destra?)) per la foglia idx."""
    level = [H(x) for x in leaves]
    proof = []
    while len(level) > 1:
        if len(level) % 2:
            level.append(level[-1])
        sib = idx ^ 1
        proof.append((level[sib], sib > idx))
        level = [H(level[i] + level[i + 1]) for i in range(0, len(level), 2)]
        idx //= 2
    return level[0], proof

def verify_proof(leaf, proof, root):
    h = H(leaf)
    for sib, right in proof:
        h = H(h + sib) if right else H(sib + h)
    return h == root

# --- Chain A: validatori con potere di voto; le "firme" sono HMAC con chiave segreta
VALS = {"v1": (b"k1", 40), "v2": (b"k2", 30), "v3": (b"k3", 20), "v4": (b"k4", 10)}

def sign(val, header):
    return hmac.new(VALS[val][0], header, "sha256").digest()

class LightClient:
    """Light client di A che vive su B: conosce i validatori di A e l'ultima radice verificata."""
    def __init__(self, vals):
        self.vals = vals
        self.total = sum(p for _, p in vals.values())
        self.roots = {}

    def update(self, height, root, sigs):
        header = height.to_bytes(8, "big") + root
        power = sum(self.vals[v][1] for v, s in sigs.items()
                    if v in self.vals and hmac.compare_digest(s, sign(v, header)))
        if 3 * power <= 2 * self.total:
            raise ValueError(f"header rifiutato: potere {power}/{self.total} non supera 2/3")
        self.roots[height] = root

    def verify_packet(self, height, packet, proof):
        return height in self.roots and verify_proof(packet, proof, self.roots[height])

# Stato di A all'altezza 10: quattro commitment di pacchetti
packets = [b"seq=1|transfer 5 uatom to bob", b"seq=2|transfer 7 uatom to carol",
           b"seq=3|transfer 1 uatom to dave", b"seq=4|transfer 9 uatom to erin"]
root, proof = merkle_root_and_proof(packets, 1)
header = (10).to_bytes(8, "big") + root

lc = LightClient(VALS)
try:
    lc.update(10, root, {v: sign(v, header) for v in ("v1", "v3")})    # 60/100
except ValueError as e:
    print(e)
lc.update(10, root, {v: sign(v, header) for v in ("v1", "v2")})        # 70/100
print("header 10 accettato con v1+v2")

print("pacchetto onesto  :", lc.verify_packet(10, packets[1], proof))
forged = b"seq=2|transfer 7000 uatom to mallory"
print("pacchetto alterato:", lc.verify_packet(10, forged, proof))

